// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount) public {
        uint256 amt = bound(amount, 1, type(uint96).max);
        vm.deal(address(this), amt);
        c.addToBalance{value: amt}();

        uint256 beforeBal = address(this).balance;
        uint256 beforeUser = c.getBalance(address(this));
        assertEq(beforeUser, amt);

        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterBal = address(this).balance;
        uint256 afterUser = c.getBalance(address(this));

        if (ok) {
            assertEq(afterBal - beforeBal, beforeUser - afterUser);
        } else {
            assertEq(afterUser, beforeUser);
        }
    }

    receive() external payable {
        revert();
    }
}
